"""
Slurm job efficiency analysis functions.
"""

import re
from datetime import datetime, timedelta
from math import ceil

EXPORT_COMMAND = ("sacct -P --units=M -S now-7days --format=JobID,JobName,User,Partition,State,Submit,Start,"
                  "Elapsed,Timelimit,AllocCPUS,TotalCPU,ReqMem,MaxRSS,AllocTRES,TRESUsageInAve > jobs.txt")

KNOWN_COLUMNS = ("JobID", "JobName", "User", "Partition", "State", "Submit", "Start", "End", "Elapsed",
                  "ElapsedRaw", "Timelimit", "AllocCPUS", "NCPUS", "TotalCPU", "CPUTime", "CPUTimeRAW", "ReqMem",
                  "MaxRSS", "AllocTRES", "ReqTRES", "ExitCode", "Account", "NNodes", "AllocNodes",
                  "TRESUsageInAve", "TRESUsageInTot", "AllocMem", "AllocGPUs")
_CANONICAL = dict((c.lower(), c) for c in KNOWN_COLUMNS)


def _canonical(name):
    """Header name in any case (e.g. 'maxrss') -> the usual sacct spelling ('MaxRSS'); unknown names unchanged."""
    name = name.strip().lstrip("﻿")
    return _CANONICAL.get(name.lower(), name)


def parse_tres(text):
    """TRES string 'billing=1,cpu=4,mem=7996M,node=1' -> {'billing': '1', 'cpu': '4', ...}; {} if empty/invalid."""
    out = {}
    for part in (text or "").split(","):
        if "=" in part:
            key, value = part.split("=", 1)
            out[key.strip()] = value.strip()
    return out


def count_gpus(tres_text):
    """Number of GPUs in a TRES string: 'gres/gpu=2' or typed 'gres/gpu:a100=2'. If both forms are listed,
    the untyped total is used (Slurm lists both for the same GPUs). 0 if none or unparseable."""
    tres = parse_tres(tres_text)
    try:
        if "gres/gpu" in tres:
            return int(float(tres["gres/gpu"]))
        return sum(int(float(v)) for k, v in tres.items() if k.startswith("gres/gpu:"))
    except (ValueError, TypeError, OverflowError):
        return 0


def _reject_fixed_width(lines):
    """sacct output without -P has space-padded columns and a '----' line: refuse it with a clear message."""
    words = lines[0].split()
    dashes = len(lines) > 1 and set(lines[1].replace(" ", "")) == {"-"}
    if len(words) > 1 or dashes:
        raise ValueError("This looks like fixed-width sacct output (exported without -P), which cannot be read "
                         "reliably. Re-export with: " + EXPORT_COMMAND)

SKIP_STATES = ("RUNNING", "PENDING", "REQUEUED", "SUSPENDED", "RESIZING")


def _finite(x):
    """Return x if it is a finite number >= 0, else None."""
    if x is None:
        return None
    try:
        x = float(x)
    except (TypeError, ValueError, OverflowError):
        return None
    if x != x or x in (float("inf"), float("-inf")) or x < 0:
        return None
    return x


def _safe(fn, *args):
    """Call a parser; any parsing error or non-finite/negative result becomes None."""
    try:
        return _finite(fn(*args))
    except (ValueError, TypeError, OverflowError, IndexError, AttributeError):
        return None


def parse_timestamp(text):
    """Timestamp -> datetime, or None. Accepts sacct text ('YYYY-MM-DDTHH:MM:SS', or with a space) and Unix
    seconds as used by published datasets (returned as UTC)."""
    text = (text or "").strip()
    if text.isdigit() and 9 <= len(text) <= 11:
        try:
            return datetime(1970, 1, 1) + timedelta(seconds=int(text))  # UTC; works on Python 3.6 to 3.13+
        except (ValueError, OverflowError, OSError):
            return None
    return _parse_timestamp_text(text)


def _parse_timestamp_text(text):
    """sacct timestamp 'YYYY-MM-DDTHH:MM:SS' (or with a space) -> datetime, or None ('Unknown', 'None', '', invalid)."""
    try:
        return datetime.strptime(text, "%Y-%m-%dT%H:%M:%S")
    except (ValueError, TypeError):
        pass
    try:
        return datetime.strptime(text, "%Y-%m-%d %H:%M:%S")
    except (ValueError, TypeError):
        pass
    return None


def parse_duration(text):
    """Slurm duration -> seconds, or None if missing or unparseable."""
    return _safe(_parse_duration_unsafe, text)


def _parse_duration_unsafe(text):
    """
    Parse Slurm duration strings into seconds.
    
    Args:
        text: Duration string in formats like "MM:SS", "MM:SS.fff", "HH:MM:SS", "D-HH:MM:SS"
        
    Returns:
        float | None: Duration in seconds, or None for None, "", "UNLIMITED", "Partition_Limit", "INVALID" or unparseable
    """
    if text is not None and re.match(r"^\s*\d+(\.\d+)?\s*$", str(text)):
        return float(text)  # a plain number means seconds (published datasets, Slurm *Raw fields)
    if text is None or text == "" or text in ("UNLIMITED", "Partition_Limit", "INVALID"):
        return None
    
    # Handle D-HH:MM:SS format
    if "-" in text:
        days, time_part = text.split("-", 1)
        days = int(days)
        hours, minutes, seconds = map(float, time_part.split(":"))
        total_seconds = days * 24 * 3600 + hours * 3600 + minutes * 60 + seconds
    # Handle HH:MM:SS format
    elif text.count(":") == 2:
        hours, minutes, seconds = map(float, text.split(":"))
        total_seconds = hours * 3600 + minutes * 60 + seconds
    # Handle MM:SS or MM:SS.fff format
    else:
        minutes, seconds = map(float, text.split(":"))
        total_seconds = minutes * 60 + seconds
    
    return total_seconds


def parse_mem_mb(text):
    """Memory string -> MB, or None if missing or unparseable."""
    return _safe(_parse_mem_mb_unsafe, text)


def _parse_mem_mb_unsafe(text):
    """
    Parse memory strings with optional suffixes into MB.
    
    Args:
        text: Memory string like "4200M", "3.5G", "2048K", "1T", or "512"
        
    Returns:
        float | None: Memory in MB, or None for None, "" or unparseable
    """
    if text is None or text == "":
        return None
    
    # Remove whitespace
    text = text.strip()
    
    # Handle suffixes
    if text.endswith("K"):
        value = float(text[:-1])
        result = value / 1024
    elif text.endswith("M"):
        value = float(text[:-1])
        result = value
    elif text.endswith("G"):
        value = float(text[:-1])
        result = value * 1024
    elif text.endswith("T"):
        value = float(text[:-1])
        result = value * 1024 * 1024
    else:
        # No suffix, assume MB
        try:
            result = float(text)
        except ValueError:
            return None
    
    return result


def parse_req_mem(text, alloc_cpus, nodes=1):
    """Requested memory -> MB (per-CPU 'c' / per-node 'n' suffix), or None if missing or unparseable."""
    return _safe(_parse_req_mem_unsafe, text, alloc_cpus, nodes)


def _parse_req_mem_unsafe(text, alloc_cpus, nodes=1):
    """
    Parse memory request with optional per-CPU or per-node suffix.
    
    Args:
        text: Memory string like "4000Mc", "16Gn", "16G"
        alloc_cpus: Number of allocated CPUs
        nodes: Number of nodes (default 1)
        
    Returns:
        float | None: Memory in MB, or None for None, "" or unparseable
    """
    if text is None or text == "":
        return None
    
    # Remove whitespace
    text = text.strip()
    
    # Check for suffixes
    if text.endswith("c"):
        # Per CPU
        mem_mb = parse_mem_mb(text[:-1])
        if mem_mb is not None:
            return mem_mb * alloc_cpus
    elif text.endswith("n"):
        # Per node
        mem_mb = parse_mem_mb(text[:-1])
        if mem_mb is not None:
            return mem_mb * nodes
    else:
        # Plain memory request
        return parse_mem_mb(text)
    
    return None


def read_sacct(text):
    """
    Read sacct output into list of dictionaries.
    
    Args:
        text: sacct output with header line and rows
        
    Returns:
        list[dict]: List of row dictionaries with stripped keys and values
    """
    if not text:
        return []
    
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    
    if not lines:
        return []
    
    # Determine delimiter from header
    header_line = lines[0]
    if "\t" in header_line:
        delimiter = "\t"
    elif "|" in header_line:
        delimiter = "|"
    elif "," in header_line:
        delimiter = ","
    else:
        _reject_fixed_width(lines)
        delimiter = "|"
    
    # Parse header
    headers = [_canonical(h) for h in header_line.split(delimiter)]
    
    # Parse rows
    result = []
    for line in lines[1:]:
        values = [v.strip() for v in line.split(delimiter)]
        # Skip if this line's values match the header names exactly
        if [_canonical(v) for v in values] == headers:
            continue
        row_dict = {}
        for i, header in enumerate(headers):
            if i < len(values):
                row_dict[header] = values[i].upper() if header == "State" else values[i]
            else:
                row_dict[header] = ""
        result.append(row_dict)
    
    return result


def merge_steps(rows):
    """
    Group rows by JobID prefix and merge steps into parent jobs.
    
    Args:
        rows: List of job dictionaries from read_sacct
        
    Returns:
        list[dict]: Merged job dictionaries with max MaxRSS
    """
    # Group by base JobID (before first ".")
    job_groups = {}
    for row in rows:
        job_id = row["JobID"]
        # Split on "." to get base job ID
        base_job_id = job_id.split(".", 1)[0]
        
        if base_job_id not in job_groups:
            job_groups[base_job_id] = []
        job_groups[base_job_id].append(row)
    
    # Merge steps into parents
    merged_jobs = []
    for base_job_id, job_list in job_groups.items():
        # Find parent (job without ".")
        parent_row = None
        step_rows = []
        
        for row in job_list:
            if "." not in row["JobID"]:
                parent_row = row
            else:
                step_rows.append(row)
        
        # If no parent, skip this group
        if parent_row is None:
            continue
            
        # Create merged job (copy parent)
        merged_job = dict(parent_row)
        
        # Find max MaxRSS among all steps and parent, keeping original text format
        max_rss_mb = None
        winning_row = None
        for row in [parent_row] + step_rows:
            if "MaxRSS" in row and row["MaxRSS"]:
                rss_mb = parse_mem_mb(row["MaxRSS"])
                if rss_mb is not None:
                    if max_rss_mb is None or rss_mb > max_rss_mb:
                        max_rss_mb = rss_mb
                        winning_row = row
        
        # Set the MaxRSS to the original text of the row with maximum value
        if winning_row is not None and "MaxRSS" in winning_row and winning_row["MaxRSS"]:
            merged_job["MaxRSS"] = winning_row["MaxRSS"]
        else:
            merged_job["MaxRSS"] = ""
        
        # Highest GPU utilisation recorded on the job or any of its steps (TRESUsageInAve gres/gpuutil)
        utils = [_safe(float, parse_tres(r.get("TRESUsageInAve")).get("gres/gpuutil")) for r in [parent_row] + step_rows]
        utils = [u for u in utils if u is not None]
        merged_job["_gpu_util"] = str(max(utils)) if utils else ""

        # Slurm often marks the job FAILED while the step that died is OUT_OF_MEMORY: report the real cause
        if not merged_job.get("State", "").startswith("COMPLETED") and any(
                r.get("State", "").startswith("OUT_OF_MEMORY") for r in step_rows):
            merged_job["State"] = "OUT_OF_MEMORY"
        merged_jobs.append(merged_job)
    
    return merged_jobs


def _start_date(job):
    """Job start date 'YYYY-MM-DD' (falls back to Submit if Start is Unknown/None), or None."""
    ts = parse_timestamp(job.get("Start")) or parse_timestamp(job.get("Submit"))
    return ts.date().isoformat() if ts else None


def summarize_trend(results):
    """Group jobs by day (when the export spans 14 days or less) or by week (named after its Monday), oldest first."""
    dated = [j for j in results if j.get("start_date")]
    if not dated:
        return {"period": None, "rows": []}
    days = sorted(datetime.strptime(j["start_date"], "%Y-%m-%d").date() for j in dated)
    period = "day" if (days[-1] - days[0]).days <= 14 else "week"

    def key(day_text):
        if period == "day":
            return day_text
        d = datetime.strptime(day_text, "%Y-%m-%d").date()
        return (d - timedelta(days=d.weekday())).isoformat()

    tagged = [dict(j, period=key(j["start_date"])) for j in dated]
    rows = summarize_groups(tagged, "period")
    rows.sort(key=lambda r: r["name"])
    return {"period": period, "rows": rows}


def analyze_job(job):
    """
    Analyze a single job and generate metrics and recommendations.
    
    Args:
        job: Dictionary with job data
        
    Returns:
        dict: Analysis results with metrics and recommendations
    """
    # Extract values
    job_id = job.get("JobID", "")
    name = job.get("JobName", "")
    state = job.get("State", "")
    elapsed_str = job.get("Elapsed", "")
    timelimit_str = job.get("Timelimit", "")
    tres = parse_tres(job.get("AllocTRES")) or parse_tres(job.get("ReqTRES"))
    alloc_cpus_str = job.get("AllocCPUS") or job.get("NCPUS") or tres.get("cpu", "")
    total_cpu_str = job.get("TotalCPU", "")
    req_mem_str = job.get("ReqMem") or tres.get("mem", "") or job.get("AllocMem", "")
    max_rss_str = job.get("MaxRSS", "")
    alloc_gpus = count_gpus(job.get("AllocTRES") or job.get("ReqTRES"))
    if not alloc_gpus:
        alloc_gpus = int(_safe(float, job.get("AllocGPUs")) or 0)
    gpu_util = _safe(float, job.get("_gpu_util")) if alloc_gpus else None
    
    # Parse durations
    elapsed_s = parse_duration(elapsed_str)
    timelimit_s = parse_duration(timelimit_str)
    total_cpu_s = parse_duration(total_cpu_str)
    
    # Parse CPU count
    alloc_cpus = _safe(float, alloc_cpus_str)
    alloc_cpus = int(alloc_cpus) if alloc_cpus is not None and alloc_cpus == int(alloc_cpus) else 0
    
    # Parse memory values
    req_mem_mb = parse_req_mem(req_mem_str, alloc_cpus)
    max_rss_mb = parse_mem_mb(max_rss_str)
    
    # Calculate metrics
    cpu_efficiency = None
    memory_efficiency = None
    time_used = None
    wasted_core_hours = None
    
    if elapsed_s is not None and elapsed_s > 0:
        if total_cpu_s is not None:
            cpu_efficiency = (total_cpu_s / (elapsed_s * alloc_cpus)) * 100 if alloc_cpus > 0 else None
        
        if req_mem_mb is not None and req_mem_mb > 0:
            memory_efficiency = (max_rss_mb / req_mem_mb) * 100 if max_rss_mb is not None else None
    
    if elapsed_s is not None and timelimit_s is not None and timelimit_s > 0:
        time_used = (elapsed_s / timelimit_s) * 100
    
    if elapsed_s is not None and total_cpu_s is not None:
        wasted_core_hours = max(0, (elapsed_s * alloc_cpus - total_cpu_s) / 3600)

    # Calculate wait time in seconds
    submit_str = job.get("Submit", "")
    start_str = job.get("Start", "")
    wait_s = None
    if submit_str and start_str and submit_str != "Unknown" and start_str != "None":
        submit_dt = parse_timestamp(submit_str)
        start_dt = parse_timestamp(start_str)
        if submit_dt and start_dt:
            # Only calculate wait time if start is after or equal to submit
            diff = (start_dt - submit_dt).total_seconds()
            if diff >= 0:
                wait_s = diff

    # Generate recommendations
    
    # Generate recommendations
    recommendations = []
    
    # Check for out of memory or timeout states
    if state.startswith("OUT_OF_MEMORY"):
        rec = "Job ran out of memory: request more memory"
        if max_rss_mb is not None:
            mem_req = ceil(max_rss_mb * 1.5)
            rec += f" (e.g. --mem={mem_req}M)."
        else:
            rec += "."
        recommendations.append(rec)
    elif state.startswith("TIMEOUT"):
        recommendations.append("Job hit its time limit: request more time or add checkpointing.")
    
    completed = state.startswith("COMPLETED")
    if completed and gpu_util is not None and alloc_gpus >= 1 and gpu_util < 50:
        new_gpus = max(1, ceil(alloc_gpus * gpu_util / 100 * 1.2))
        if alloc_gpus > 1 and new_gpus < alloc_gpus:
            recommendations.append("GPU utilisation is %.1f%% on %d GPUs: request --gpus=%d instead, or check the work "
                                   "is spread across all GPUs." % (gpu_util, alloc_gpus, new_gpus))
        elif gpu_util < 30:
            recommendations.append("GPU utilisation is %.1f%% on %d GPU%s: check that the job really uses the GPU."
                                   % (gpu_util, alloc_gpus, "" if alloc_gpus == 1 else "s"))
    # CPU efficiency recommendation
    if completed and cpu_efficiency is not None and cpu_efficiency < 50 and alloc_cpus > 1:
        new_cpus = max(1, ceil(alloc_cpus * cpu_efficiency / 100 * 1.2))
        recommendations.append(f"CPU efficiency is {cpu_efficiency:.1f}%: request --cpus-per-task={new_cpus} CPUs instead of {alloc_cpus}, or check the code really runs in parallel.")
    
    if completed and memory_efficiency is not None and memory_efficiency < 50:
        new_mem = ceil(max_rss_mb * 1.25) if max_rss_mb is not None else None
        if new_mem is not None and req_mem_mb - new_mem >= 1024:
            recommendations.append(f"Memory efficiency is {memory_efficiency:.1f}%: request --mem={new_mem}M instead.")
    
    # High memory efficiency warning
    if memory_efficiency is not None and memory_efficiency > 90 and not state.startswith("OUT_OF_MEMORY"):
        recommendations.append(f"Peak memory is {memory_efficiency:.1f}% of the request: the job is close to its memory limit, request a little more to be safe.")
    
    # Time usage recommendation
    if completed and elapsed_s is not None and elapsed_s > 0 and time_used is not None and time_used < 25:
        # Calculate new time limit (elapsed * 1.5 rounded up to next 15 min)
        new_time_limit_s = elapsed_s * 1.5
        # Round up to next multiple of 900 seconds (15 minutes)
        rounded_seconds = ceil(new_time_limit_s / 900) * 900
        
        # Convert back to HH:MM:SS format
        hours = int(rounded_seconds // 3600)
        minutes = int((rounded_seconds % 3600) // 60)
        seconds = int(rounded_seconds % 60)
        new_limit_str = f"{hours:02d}:{minutes:02d}:{seconds:02d}"
        
        recommendations.append(f"Only {time_used:.1f}% of the time limit was used: request --time={new_limit_str} instead.")
    
    return {
        "job_id": job_id,
        "name": name,
        "state": state,
        "elapsed_s": elapsed_s,
        "alloc_cpus": alloc_cpus,
        "cpu_efficiency": cpu_efficiency,
        "memory_efficiency": memory_efficiency,
        "time_used": time_used,
        "wasted_core_hours": wasted_core_hours,
        "wait_s": wait_s,
        "array_id": job_id.split(".")[0].split("_")[0] if "_" in job_id.split(".")[0] else None,
        "max_rss_mb": max_rss_mb,
        "req_mem_mb": req_mem_mb,
        "alloc_gpus": alloc_gpus,
        "gpu_hours": alloc_gpus * elapsed_s / 3600 if alloc_gpus and elapsed_s is not None else None,
        "gpu_utilization": gpu_util,
        "start_date": _start_date(job),
        "recommendations": recommendations,
        "user": job.get("User", "") or "",
        "partition": job.get("Partition", "") or ""
    }


def summarize_groups(results, key):
    """Group analysed jobs by results[i][key]; return a list of dicts sorted by wasted_core_hours (desc), then name."""
    # name = the value, or "(unknown)" if it is "".
    # each group dict: {"name", "job_count", "avg_cpu_efficiency", "avg_memory_efficiency", "wasted_core_hours"}
    # averages ignore None values and are None if nothing to average; wasted_core_hours sums non-None values (0.0 if none).
    # sort: key=lambda g: (-g["wasted_core_hours"], g["name"])
    
    groups = {}
    for job in results:
        value = job.get(key, "")
        if value == "":
            name = "(unknown)"
        else:
            name = value
        if name not in groups:
            groups[name] = {
                "name": name,
                "job_count": 0,
                "avg_cpu_efficiency": None,
                "avg_memory_efficiency": None,
                "wasted_core_hours": 0.0,
                "avg_wait_s": None,
                "gpu_hours": None,
                "_cpu_n": 0,
                "_mem_n": 0,
                "_wait_n": 0
            }
        group = groups[name]
        group["job_count"] += 1
        
        # Handle wasted core hours (sum)
        wasted_core_hours = job.get("wasted_core_hours")
        if wasted_core_hours is not None:
            group["wasted_core_hours"] += wasted_core_hours
        
        # Handle averages
        cpu_eff = job.get("cpu_efficiency")
        mem_eff = job.get("memory_efficiency")
        
        if cpu_eff is not None:
            if group["avg_cpu_efficiency"] is None:
                group["avg_cpu_efficiency"] = cpu_eff
            else:
                group["avg_cpu_efficiency"] += cpu_eff
            group["_cpu_n"] += 1
        
        if mem_eff is not None:
            if group["avg_memory_efficiency"] is None:
                group["avg_memory_efficiency"] = mem_eff
            else:
                group["avg_memory_efficiency"] += mem_eff
            group["_mem_n"] += 1

        if job.get("gpu_hours") is not None:
            group["gpu_hours"] = (group["gpu_hours"] or 0) + job["gpu_hours"]

        wait_s = job.get("wait_s")
        if wait_s is not None:
            group["avg_wait_s"] = (group["avg_wait_s"] or 0) + wait_s
            group["_wait_n"] += 1

    # Convert sums to averages where applicable
    for group in groups.values():
        if group["avg_cpu_efficiency"] is not None:
            group["avg_cpu_efficiency"] /= group["_cpu_n"]
        if group["avg_memory_efficiency"] is not None:
            group["avg_memory_efficiency"] /= group["_mem_n"]
        if group["avg_wait_s"] is not None:
            group["avg_wait_s"] /= group["_wait_n"]

        # Remove helper keys
        del group["_cpu_n"]
        del group["_mem_n"]
        del group["_wait_n"]
    
    # Convert to list and sort
    result = list(groups.values())
    result.sort(key=lambda g: (-g["wasted_core_hours"], g["name"]))
    
    return result


